package com.troday.api.entity;
import jakarta.persistence.*; import java.time.LocalDateTime;
@Entity @Table(name="room_viewing_proposals",uniqueConstraints=@UniqueConstraint(columnNames={"tenant_id","client_request_key"})) public class ViewingProposal {
 @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @Column(name="room_id",nullable=false) private Long roomId; @Column(name="house_id",nullable=false) private Long houseId; @Column(name="conversation_id",nullable=false) private Long conversationId; @Column(name="tenant_id",nullable=false) private Long tenantId; @Column(name="landlord_id",nullable=false) private Long landlordId; @Column(name="client_request_key",nullable=false) private String clientRequestKey; @Column(name="starts_at",nullable=false) private LocalDateTime startsAt; @Column(name="ends_at",nullable=false) private LocalDateTime endsAt; private String notes; @Column(nullable=false) private String status="PENDING"; @Column(name="reviewed_by_id") private Long reviewedById; @Column(name="reviewed_at") private LocalDateTime reviewedAt; @Column(name="rejection_reason") private String rejectionReason; @Column(name="withdrawn_by_id") private Long withdrawnById; @Column(name="withdrawn_at") private LocalDateTime withdrawnAt; @Column(name="expired_at") private LocalDateTime expiredAt; @Column(name="scheduled_viewing_id") private Long scheduledViewingId;
 public Long getId(){return id;} public Long getRoomId(){return roomId;} public void setRoomId(Long v){roomId=v;} public Long getHouseId(){return houseId;} public void setHouseId(Long v){houseId=v;} public Long getConversationId(){return conversationId;} public void setConversationId(Long v){conversationId=v;} public Long getTenantId(){return tenantId;} public void setTenantId(Long v){tenantId=v;} public Long getLandlordId(){return landlordId;} public void setLandlordId(Long v){landlordId=v;} public String getClientRequestKey(){return clientRequestKey;} public void setClientRequestKey(String v){clientRequestKey=v;} public LocalDateTime getStartsAt(){return startsAt;} public void setStartsAt(LocalDateTime v){startsAt=v;} public LocalDateTime getEndsAt(){return endsAt;} public void setEndsAt(LocalDateTime v){endsAt=v;} public String getNotes(){return notes;} public void setNotes(String v){notes=v;} public String getStatus(){return status;} public void setStatus(String v){status=v;} public Long getReviewedById(){return reviewedById;} public void setReviewedById(Long v){reviewedById=v;} public LocalDateTime getReviewedAt(){return reviewedAt;} public void setReviewedAt(LocalDateTime v){reviewedAt=v;} public String getRejectionReason(){return rejectionReason;} public void setRejectionReason(String v){rejectionReason=v;} public Long getWithdrawnById(){return withdrawnById;} public void setWithdrawnById(Long v){withdrawnById=v;} public LocalDateTime getWithdrawnAt(){return withdrawnAt;} public void setWithdrawnAt(LocalDateTime v){withdrawnAt=v;} public LocalDateTime getExpiredAt(){return expiredAt;} public void setExpiredAt(LocalDateTime v){expiredAt=v;} public Long getScheduledViewingId(){return scheduledViewingId;} public void setScheduledViewingId(Long v){scheduledViewingId=v;}
}
